function def = f90_xrobo02_definition
%F90_XROBO02_DEFINITION Dual-arm torque-control task grounded in ABB YuMi.
% Public ranges and the current evaluation interface are defined here.

def = struct;
def.id = "XROBO02";
def.formal_id = "F90-XROBO-02";
def.sim = struct("step",0.002,"stop",8.0);
def.source = struct( ...
    "url","https://github.com/mathworks/Industrial-Robots-Simscape", ...
    "tag","25.1.1.3", ...
    "commit","0f7d25f891f9665293b17a4153168eacd2a377d5", ...
    "license","MathWorks permissive 3-clause, MathWorks-products restriction", ...
    "model","reference/files/Industrial-Robots-Simscape/Robots/abbYuMi/Models/sm_abbYuMi_trajectory.slx");

qL = [-0.77437 -0.91696 2.3837 0.73389 0.63165 -0.61014 -2.2714];
qR = [0.69837 -0.76268 -2.3821 0.81511 2.3751 0.60993 -0.68711];
dq = [0.22 0.16 0.20 0.12 0.20 0.16 0.22];
limits = [42 42 28 24 14 12 10 42 42 28 24 14 12 10];

def.initial_joint_position_rad = [pi/4 zeros(1,6) -pi/4 zeros(1,6)];
def.unscaled_torque_limits_nm = limits;
def.public_inputs = [ ...
    pin("left_target_rad",qL,qL-dq,qL+dq,"rad", ...
        "desired final positions of the left arm's seven serial joints"), ...
    pin("right_target_rad",qR,qR-dq,qR+dq,"rad", ...
        "desired final positions of the right arm's seven serial joints"), ...
    pin("move_duration",4.2,3.2,5.2,"s", ...
        "duration of the coordinated point-to-point move"), ...
    pin("shared_payload_mass",0.55,0.2,1.0,"kg", ...
        "mass parameter for the payload-equivalent generalized load shared across the two arms"), ...
    pin("torque_limit_scale",1.0,0.75,1.15,"1", ...
        "common scale on all fourteen actuator torque limits"), ...
    pin("disturbance_torque_nm",zeros(1,14),-disturbance_limit(), ...
        disturbance_limit(),"N*m", ...
        "temporary external generalized load on the fourteen joints"), ...
    pin("disturbance_start",4.8,2.8,6.1,"s", ...
        "start time of the temporary external load")];

def.outputs = [ ...
    pout("joint_state",28, ...
        "[qL1..qL7,qR1..qR7,dqL1..dqL7,dqR1..dqR7]", ...
        "positions and velocities derived from physical joint sensors"), ...
    pout("end_effector_pose",12, ...
        "[left xyz,rpy,right xyz,rpy] in metre and rad", ...
        "poses calculated from measured physical joint positions and pinned YuMi geometry"), ...
    pout("joint_torque",14, ...
        "[left tau1..tau7,right tau1..tau7] in N*m", ...
        "bounded actuator commands before the external-load contribution"), ...
    pout("coordination_state",4, ...
        "[left progress,right progress,progress mismatch,gripper separation]", ...
        "coordination quantities calculated from measured physical states")];

def.prompt = strjoin([ ...
    "Build a finite-inertia dual-arm robot with two seven-revolute-joint arms and genuine closed-loop torque actuation. Both arms must execute a coordinated point-to-point motion under a shared payload-equivalent load, respect finite joint-torque limits, remain stable, and recover after a temporary external joint load. Prescribing joint motion, replaying a stored trajectory as measured output, or assigning the requested pose directly is not a valid implementation.", ...
    "Read left_target_rad, right_target_rad, move_duration, shared_payload_mass, torque_limit_scale, disturbance_torque_nm, and disturbance_start from MATLAB base-workspace variables. The seven left and right targets operate within the published min/max arrays in the task specification; move_duration is 3.2--5.2 s, shared_payload_mass is 0.2--1.0 kg, torque_limit_scale is 0.75--1.15, and disturbance_start is 2.8--6.1 s. The fourteen disturbance components operate within the published componentwise bounds and act temporarily after disturbance_start.", ...
    "The unscaled joint-torque limits are [42,42,28,24,14,12,10] N*m for each arm. Across the declared ranges, both measured end effectors must reach the poses implied by their requested joint targets, the two arms must remain synchronized during the coordinated move, and the mechanism must settle after both the move and the temporary load.", ...
    "Log Timeseries joint_state, end_effector_pose, joint_torque, and coordination_state. joint_state contains measured [qL1..qL7,qR1..qR7,dqL1..dqL7,dqR1..dqR7]. end_effector_pose contains measured [left xyz,rpy,right xyz,rpy] in a fixed right-handed base frame. joint_torque contains the fourteen bounded actuator commands in N*m. coordination_state contains left progress, right progress, their absolute mismatch, and measured gripper separation. Logs must arise from the causal closed-loop plant rather than copied commands or precomputed output trajectories.", ...
    "Work directly in the required model file and keep the latest usable state saved at that path throughout the task."], sprintf("\n\n"));

def.scenarios = [ ...
    scenario("heavy_low_limit", struct( ...
        "left_target_rad",qL+[.18 -.12 .10 -.08 .12 -.10 .14], ...
        "right_target_rad",qR+[-.17 .13 -.11 .08 -.15 .10 -.13], ...
        "move_duration",3.35,"shared_payload_mass",0.96, ...
        "torque_limit_scale",0.78, ...
        "disturbance_torque_nm",[0 -4.2 2.4 0 -1.5 0.8 0 0 4.0 -2.3 0 1.4 -0.8 0], ...
        "disturbance_start",3.72)), ...
    scenario("opposite_corner", struct( ...
        "left_target_rad",qL+[-.20 .14 -.16 .10 -.17 .12 -.18], ...
        "right_target_rad",qR+[.19 -.14 .17 -.10 .18 -.12 .17], ...
        "move_duration",4.85,"shared_payload_mass",0.72, ...
        "torque_limit_scale",0.88, ...
        "disturbance_torque_nm",[3.7 0 -2.1 1.5 0 -0.8 .5 -3.5 0 2.0 -1.4 0 .8 -.5], ...
        "disturbance_start",5.18)), ...
    scenario("fast_asymmetric_load", struct( ...
        "left_target_rad",qL+[.11 .09 -.18 -.09 .18 .13 -.16], ...
        "right_target_rad",qR+[-.08 -.12 .19 .08 -.16 -.13 .16], ...
        "move_duration",3.25,"shared_payload_mass",0.88, ...
        "torque_limit_scale",0.76, ...
        "disturbance_torque_nm",[-3.8 3.2 0 -1.8 1.2 0 -.6 3.4 -3.1 0 1.7 -1.1 0 .6], ...
        "disturbance_start",2.94)), ...
    scenario("interior_recovery", struct( ...
        "left_target_rad",qL+[.07 -.08 .09 .06 -.11 .07 .10], ...
        "right_target_rad",qR+[-.06 .09 -.08 -.06 .12 -.07 -.09], ...
        "move_duration",4.45,"shared_payload_mass",0.48, ...
        "torque_limit_scale",0.94, ...
        "disturbance_torque_nm",[2.4 -2.8 1.6 0 -.9 .5 0 -2.2 2.7 -1.5 0 .8 -.5 0], ...
        "disturbance_start",4.58))];

def.groups = struct( ...
    "G","load/update/simulate and complete Timeseries contract", ...
    "A","dual-arm terminal joint and end-effector accuracy", ...
    "Q","smoothness, synchronization and actuator-bound quality", ...
    "M","fourteen-joint sensor-to-controller-to-torque-to-plant causal mechanism", ...
    "R","worst declared target, payload and torque-limit operating point", ...
    "D","temporary external-load response and post-event recovery", ...
    "weights",struct("A",.15,"Q",.10,"M",.30,"R",.20,"D",.25));
end

function v = disturbance_limit
v = [5 5 3 2 1.8 1.2 .8 5 5 3 2 1.8 1.2 .8];
end
function s = pin(name, nominal, minv, maxv, unit, meaning)
s = struct("name",name,"nominal",nominal,"min",minv,"max",maxv, ...
    "unit",unit,"meaning",meaning);
end
function s = pout(name, channels, order, source)
s = struct("name",name,"channels",channels,"order",order,"unit","mixed", ...
    "physical_source",source);
end
function s = scenario(id, values)
s = struct("id",id,"values",values);
end
